import "../../styles/index-base.css";
import "../../styles/components/tooltip.css";
import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip";
import { cn } from "../../lib/cn";

export function TooltipProvider({ delay = 350, ...props }: TooltipPrimitive.Provider.Props) {
  return <TooltipPrimitive.Provider delay={delay} {...props} />;
}

export function Tooltip(props: TooltipPrimitive.Root.Props) {
  return <TooltipPrimitive.Root data-slot="tooltip" {...props} />;
}

export function TooltipTrigger(props: TooltipPrimitive.Trigger.Props) {
  return <TooltipPrimitive.Trigger data-slot="tooltip-trigger" {...props} />;
}

type TooltipContentProps = TooltipPrimitive.Popup.Props &
  Pick<TooltipPrimitive.Positioner.Props, "align" | "alignOffset" | "side" | "sideOffset">;

export function TooltipContent({
  className,
  side = "top",
  sideOffset = 6,
  align = "center",
  alignOffset = 0,
  children,
  ...props
}: TooltipContentProps) {
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Positioner
        className="ix-positioner"
        side={side}
        sideOffset={sideOffset}
        align={align}
        alignOffset={alignOffset}
      >
        <TooltipPrimitive.Popup className={cn("ix-tooltip", className)} {...props}>
          {children}
          <TooltipPrimitive.Arrow className="ix-tooltip__arrow" />
        </TooltipPrimitive.Popup>
      </TooltipPrimitive.Positioner>
    </TooltipPrimitive.Portal>
  );
}

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-positioner { z-index: var(--ix-layer-flyout); }

.ix-tooltip kbd { font-family: inherit; font-size: 10px; color: var(--ix-ink-tertiary); }

.ix-tooltip { display: flex; align-items: center; gap: 8px; max-width: 240px; padding: 6px 8px; border-radius: 5px; background: var(--ix-inverse); color: var(--ix-on-inverse); font-size: 12px; line-height: 1.35; box-shadow: 0 5px 18px rgba(0, 0, 0, 0.18); transform-origin: var(--transform-origin); transition: opacity var(--ix-enter-duration) var(--ix-ease-out), transform var(--ix-enter-duration) var(--ix-ease-out); }

.ix-tooltip[data-starting-style] { opacity: 0; transform: scale(0.96); }

.ix-tooltip[data-ending-style] { opacity: 0; transform: scale(0.98); transition-duration: var(--ix-exit-duration); }

.ix-tooltip[data-instant] { transition-duration: 0ms; }

.ix-tooltip kbd { padding: 0 3px; border: 1px solid color-mix(in oklch, var(--ix-on-inverse) 24%, transparent); border-radius: 3px; color: color-mix(in oklch, var(--ix-on-inverse) 76%, transparent); }

.ix-tooltip__arrow { width: 8px; height: 4px; fill: var(--ix-inverse); }

:root[data-theme="dark"] .ix-tooltip__arrow { fill: var(--ix-inverse); }

@media (prefers-reduced-motion: reduce) {
.ix-tooltip {
    transition-property: opacity;
    transition-duration: var(--ix-exit-duration);
  }

.ix-tooltip[data-starting-style],
.ix-tooltip[data-ending-style] { transform: none; }
}
}
